import { JwsSigningInput, prepareJwsSigningInput } from './signVerifiablePresentation'

/**
 * A crypto provider and non-extractable private key obtained from the Fortify
 * certificate selection dialog (see web-crypto/fortify.ts).
 */
export interface HsmSigner {
  provider: any
  privateKey: any
  alg: string
}

interface HsmWebCryptoAlgorithm {
  name: string
  hash: string
  saltLength?: number
}

const WEB_CRYPTO_ALGORITHMS: Record<string, HsmWebCryptoAlgorithm> = {
  ES256: { name: 'ECDSA', hash: 'SHA-256' },
  ES384: { name: 'ECDSA', hash: 'SHA-384' },
  ES512: { name: 'ECDSA', hash: 'SHA-512' },
  RS256: { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' },
  RS384: { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-384' },
  RS512: { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-512' },
  PS256: { name: 'RSA-PSS', hash: 'SHA-256', saltLength: 32 },
  PS384: { name: 'RSA-PSS', hash: 'SHA-384', saltLength: 48 },
  PS512: { name: 'RSA-PSS', hash: 'SHA-512', saltLength: 64 }
}

const COORDINATE_LENGTHS: Record<string, number> = {
  ES256: 32,
  ES384: 48,
  ES512: 66
}

function bytesToBase64Url(bytes: Uint8Array): string {
  let binary = ''
  for (let i = 0; i < bytes.length; i++) {
    binary += String.fromCharCode(bytes[i])
  }
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

/**
 * Convert a DER encoded ECDSA signature (SEQUENCE of two INTEGERs) into the raw
 * P1363 format expected in JWS: r and s left-padded to the coordinate length.
 */
export function derSignatureToRaw(der: Uint8Array, coordinateLength: number): Uint8Array {
  let i = 2
  if (der[i++] !== 0x02) throw new Error('Invalid ECDSA signature: expected INTEGER tag for r')
  const rLength = der[i++]
  const r = der.slice(i, (i += rLength))
  if (der[i++] !== 0x02) throw new Error('Invalid ECDSA signature: expected INTEGER tag for s')
  const sLength = der[i++]
  const s = der.slice(i, i + sLength)
  const stripLeadingZeros = (value: Uint8Array) => {
    let j = 0
    while (j < value.length - 1 && value[j] === 0) {
      j++
    }
    return value.slice(j)
  }
  const rTrimmed = stripLeadingZeros(r)
  const sTrimmed = stripLeadingZeros(s)
  const raw = new Uint8Array(coordinateLength * 2)
  raw.set(rTrimmed, coordinateLength - rTrimmed.length)
  raw.set(sTrimmed, coordinateLength * 2 - sTrimmed.length)
  return raw
}

export async function signJwsWithHsm(signingInput: JwsSigningInput, hsm: HsmSigner): Promise<string> {
  const webCryptoAlgorithm = WEB_CRYPTO_ALGORITHMS[hsm.alg]
  if (!webCryptoAlgorithm) {
    throw new Error(`Unsupported HSM signature algorithm: ${hsm.alg}`)
  }
  if (hsm.alg.startsWith('ES') && !COORDINATE_LENGTHS[hsm.alg]) {
    throw new Error(`Unsupported ECDSA algorithm: ${hsm.alg}`)
  }

  const encodedHeader = bytesToBase64Url(new TextEncoder().encode(JSON.stringify(signingInput.header)))
  const encodedPayload = bytesToBase64Url(new TextEncoder().encode(signingInput.payload))
  const tbsBytes = new TextEncoder().encode(`${encodedHeader}.${encodedPayload}`)

  let signature = new Uint8Array(await hsm.provider.subtle.sign(webCryptoAlgorithm, hsm.privateKey, tbsBytes))
  if (hsm.alg.startsWith('ES') && signature[0] === 0x30) {
    // PKCS#11-backed providers (Fortify) return DER encoded ECDSA signatures,
    // while the browser WebCrypto returns the raw P1363 format expected in JWS
    signature = derSignatureToRaw(signature, COORDINATE_LENGTHS[hsm.alg])
  }

  return `${encodedHeader}.${encodedPayload}.${bytesToBase64Url(signature)}`
}

export async function signDocumentAsJwtWithHsm(
  document: any,
  hsm: HsmSigner,
  neverExpires = false,
  validUntil: Date | null = null,
  verificationMethod?: string,
  issuerOverride?: string
): Promise<string> {
  const signingInput = await prepareJwsSigningInput(document, hsm.alg, neverExpires, validUntil, verificationMethod, issuerOverride)
  return signJwsWithHsm(signingInput, hsm)
}

/**
 * Sign several documents one after the other: a PKCS#11 session cannot run
 * concurrent signing operations, parallel provider.subtle.sign calls fail
 * with CKR_OPERATION_ACTIVE.
 */
export async function signDocumentsAsJwtWithHsm(
  documents: any[],
  hsm: HsmSigner,
  neverExpires = false,
  validUntil: Date | null = null,
  verificationMethod?: string,
  issuerOverride?: string
): Promise<string[]> {
  const jwts: string[] = []
  for (const document of documents) {
    jwts.push(await signDocumentAsJwtWithHsm({ ...document }, hsm, neverExpires, validUntil, verificationMethod, issuerOverride))
  }
  return jwts
}

export const signVPToJwtWithHsm = async (vp: any, hsm: HsmSigner, verificationMethod?: string, issuer?: string): Promise<string> => {
  return signDocumentAsJwtWithHsm({ ...vp }, hsm, false, null, verificationMethod, issuer)
}

export async function signDocumentWithHsm(doc: any, hsm: HsmSigner, verificationMethod: string): Promise<string> {
  if (doc.type?.includes('VerifiableCredential')) {
    return await signDocumentAsJwtWithHsm(doc, hsm, false, null, verificationMethod)
  }
  throw new Error('Unsupported document type')
}
